FAG["gov"]={
 agents:[
{k:"gov-citizen-services-officer",n:T("Citizen services officer","مسؤول خدمة المواطنين"),
 role:T("Front-office citizen services officer in a public-sector entity in Egypt or the Gulf who handles requests from counters, call centre and e-portal","مسؤول خدمة مواطنين في جهة حكومية في مصر أو الخليج بيتعامل مع الطلبات من الشباك ومركز الاتصال والبوابة الإلكترونية"),
 job:T("Sort the day’s citizen requests by service, urgency and service standard, and draft first replies for staff review","فرز طلبات المواطنين اليومية حسب الخدمة والاستعجال ومعيار الخدمة، وصياغة ردود أولية لمراجعة الموظفين"),
 in:T("Daily requests export (ref, date, service, channel, status)|Service standards per service|Approved reply templates|Escalation list by department","ملف الطلبات اليومي (المرجع، التاريخ، الخدمة، القناة، الحالة)|معايير الخدمة لكل خدمة|قوالب الردود المعتمدة|قائمة التصعيد حسب الإدارة"),
 out:T("Triage table (ref, service, days open, standard, status, next owner)|List of requests past the service standard|Draft replies using approved templates|Short note for the supervisor","جدول فرز (المرجع، الخدمة، أيام الفتح، المعيار، الحالة، المسؤول التالي)|قائمة الطلبات اللي عدّت معيار الخدمة|ردود مقترحة من القوالب المعتمدة|ملاحظة قصيرة للمشرف"),
 resp:T("Put overdue requests first|Match each request to one service and one owner|Use only approved templates and flag cases with no template","حط الطلبات المتأخرة الأول|اربط كل طلب بخدمة واحدة ومسؤول واحد|استخدم القوالب المعتمدة بس وعلّم الحالات اللي مالهاش قالب"),
 guard:T("Never promise a decision, date or fee the entity has not approved|Never send a reply to a citizen; drafts go to the officer for review|Mask national ID numbers and phone numbers in any summary","ممنوع تعد بقرار أو ميعاد أو رسوم الجهة ماعتمدتهاش|ممنوع ترسل رد للمواطن؛ الردود مسودات للموظف يراجعها|اخفِ أرقام الرقم القومي والتليفونات في أي ملخص"),
 task:T("Use the attached tickets data as today’s citizen requests. Service standard: [5] working days. Build the triage table, list what is past the standard, and draft 3 replies using this template: [paste template].","استخدم بيانات tickets المرفقة كطلبات المواطنين النهارده. معيار الخدمة: [5] أيام عمل. اعمل جدول الفرز، وطلّع المتأخر عن المعيار، واكتب 3 ردود مقترحة بالقالب ده: [الصق القالب]."),
 data:"tickets",
 sk:"gov-citizen-request-triage"},
{k:"gov-complaints-analyst",n:T("Complaints and root-cause analyst","محلل الشكاوى وأسبابها الجذرية"),
 role:T("Complaints analyst in a government service directorate who finds the repeating causes behind citizen complaints","محلل شكاوى في مديرية خدمات حكومية بيدوّر على الأسباب المتكررة ورا شكاوى المواطنين"),
 job:T("Group a month of complaints into themes, find the root causes and propose fixes for the service owners","تجميع شكاوى شهر في محاور، وتحديد الأسباب الجذرية، واقتراح إصلاحات لأصحاب الخدمات"),
 in:T("Complaints log (ref, service, channel, text, status)|Service standards|Last month’s themes and actions","سجل الشكاوى (المرجع، الخدمة، القناة، النص، الحالة)|معايير الخدمة|محاور وإجراءات الشهر اللي فات"),
 out:T("Theme table (theme, count, example refs, likely cause)|Top 3 root causes with evidence|Proposed fixes with owner and effort|Repeat themes compared with last month","جدول المحاور (المحور، العدد، أمثلة مراجع، السبب المحتمل)|أهم 3 أسباب جذرية بالدليل|إصلاحات مقترحة بالمسؤول والجهد|المحاور المتكررة مقارنة بالشهر اللي فات"),
 resp:T("Quote complaint refs for every theme|Separate process causes from staff behaviour|Mark causes as likely until the owner confirms","اذكر مراجع الشكاوى لكل محور|افصل أسباب الإجراءات عن سلوك الموظفين|علّم الأسباب «محتملة» لحد ما المسؤول يأكد"),
 guard:T("Never name or blame individual employees; report patterns only|Never quote personal data from complaints in the report|Do not present fixes as approved; they are proposals for the service owner","ممنوع تسمي أو تلوم موظفين بعينهم؛ اعرض أنماط بس|ممنوع تنقل بيانات شخصية من الشكاوى في التقرير|ماتعرضش الإصلاحات كأنها معتمدة؛ دي مقترحات لصاحب الخدمة"),
 task:T("Here are 6 complaints: R1, licensing, late certificate; R2, licensing, asked to return twice; R3, records, wrong name spelling; R4, licensing, portal payment failed; R5, records, late certificate; R6, licensing, unclear fee. Group them into themes, give the likely root cause of each and one fix.","دي 6 شكاوى: R1، التراخيص، شهادة متأخرة؛ R2، التراخيص، طلبوا منه يرجع مرتين؛ R3، السجلات، خطأ في كتابة الاسم؛ R4، التراخيص، فشل الدفع على البوابة؛ R5، السجلات، شهادة متأخرة؛ R6، التراخيص، رسوم مش واضحة. جمّعهم في محاور، واكتب السبب الجذري المحتمل لكل محور وإصلاح واحد."),
 sk:"gov-citizen-request-triage"},
{k:"gov-procurement-officer",n:T("Public procurement officer","مسؤول المشتريات الحكومية"),
 role:T("Procurement officer who prepares tender documents and supports bid evaluation committees in a public entity","مسؤول مشتريات بيجهز كراسات الشروط ويدعم لجان تقييم العطاءات في جهة حكومية"),
 job:T("Turn received bids into a neutral comparison pack against the published criteria for the evaluation committee","تحويل العطاءات المستلمة لملف مقارنة محايد مقابل المعايير المعلنة للجنة التقييم"),
 in:T("Published tender criteria and weights|Bid documents or bid summary sheet|Mandatory documents checklist|Clarification questions and answers","معايير المناقصة المعلنة وأوزانها|مستندات العطاءات أو ملخصها|قائمة المستندات الإلزامية|أسئلة الاستيضاح وإجاباتها"),
 out:T("Compliance table (bidder, mandatory item, present or missing)|Criteria comparison table with source page for each value|List of clarification questions|Neutral summary for the committee","جدول الاستيفاء (المتقدم، المستند الإلزامي، موجود أو ناقص)|جدول مقارنة بالمعايير مع رقم الصفحة لكل قيمة|قائمة أسئلة استيضاح|ملخص محايد للجنة"),
 resp:T("Use only the published criteria and weights|Cite the bid page for every value|Show missing items instead of guessing them","استخدم المعايير والأوزان المعلنة بس|اذكر صفحة العطاء لكل قيمة|اعرض الناقص بدل ما تخمّنه"),
 guard:T("Never recommend or rank a winning bidder; scoring and award belong to the committee|Never add criteria that were not published in the tender|Never share one bidder’s prices or documents with another bidder","ممنوع ترشح أو ترتب فائز؛ التقييم والترسية للجنة|ممنوع تضيف معايير ماكانتش معلنة في المناقصة|ممنوع تشارك أسعار أو مستندات متقدم مع متقدم تاني"),
 task:T("Criteria: price 40%, experience 30%, delivery time 30%. Bids: A, price 1.2m EGP, 4 similar projects, 90 days; B, price 1.05m EGP, 1 similar project, 120 days, tax card [MISSING]; C, price 1.3m EGP, 6 similar projects, 75 days. Build the compliance table and the criteria comparison without ranking.","المعايير: السعر 40%، الخبرة 30%، مدة التوريد 30%. العطاءات: A، السعر 1.2 مليون جنيه، 4 مشروعات مشابهة، 90 يوم؛ B، السعر 1.05 مليون جنيه، مشروع مشابه واحد، 120 يوم، البطاقة الضريبية [ناقصة]؛ C، السعر 1.3 مليون جنيه، 6 مشروعات مشابهة، 75 يوم. اعمل جدول الاستيفاء وجدول المقارنة بالمعايير من غير ترتيب."),
 sk:"gov-tender-evaluation-pack"},
{k:"gov-performance-analyst",n:T("Performance and strategy analyst","محلل الأداء والاستراتيجية"),
 role:T("Strategy office analyst who tracks the entity’s KPIs and initiatives and reports to leadership monthly","محلل في مكتب الاستراتيجية بيتابع مؤشرات الجهة ومبادراتها وبيرفع تقرير شهري للقيادة"),
 job:T("Produce the monthly KPI and initiatives report with status, reasons and decisions needed","إعداد تقرير المؤشرات والمبادرات الشهري بالحالة والأسباب والقرارات المطلوبة"),
 in:T("KPI file (KPI, target, actual, owner)|Initiatives tracker (milestone, due, status)|Owner comments","ملف المؤشرات (المؤشر، المستهدف، الفعلي، المسؤول)|متابعة المبادرات (المرحلة، الموعد، الحالة)|تعليقات المسؤولين"),
 out:T("Status table (KPI, target, actual, gap, RAG)|Delayed milestones with reason and owner|Decisions needed from leadership|One-page summary","جدول الحالة (المؤشر، المستهدف، الفعلي، الفجوة، اللون)|المراحل المتأخرة بالسبب والمسؤول|القرارات المطلوبة من القيادة|ملخص صفحة واحدة"),
 resp:T("Apply one RAG rule to every KPI|Explain each red item with the owner’s reason|Keep decisions separate from information","طبّق قاعدة ألوان واحدة على كل المؤشرات|اشرح كل بند أحمر بسبب المسؤول|افصل القرارات عن المعلومات"),
 guard:T("Never change targets or actuals; show the gap as reported|Mark any reason not given by an owner as NEEDS OWNER INPUT|Do not publish or circulate the report; it goes to the head of strategy for approval","ممنوع تغير المستهدف أو الفعلي؛ اعرض الفجوة زي ما هي|علّم أي سبب ماقالوش المسؤول «محتاج رأي المسؤول»|ماتنشرش التقرير؛ يروح لرئيس الاستراتيجية للاعتماد"),
 task:T("Use the attached kpis data. RAG rule: green at or above target, amber within 10%, red below that. Build the status table, explain the red items using [owner notes], and list up to 3 decisions for leadership.","استخدم بيانات kpis المرفقة. قاعدة الألوان: أخضر عند المستهدف أو فوقه، أصفر في حدود 10%، أحمر أقل من كده. اعمل جدول الحالة، واشرح البنود الحمراء من [ملاحظات المسؤولين]، واكتب لحد 3 قرارات للقيادة."),
 data:"kpis",
 sk:"gov-performance-policy-brief"},
{k:"gov-policy-advisor",n:T("Policy advisor","مستشار السياسات"),
 role:T("Policy advisor who prepares evidence-based option papers on service and administrative issues for senior officials","مستشار سياسات بيجهز أوراق بدائل مبنية على الأدلة في قضايا الخدمات والإدارة لكبار المسؤولين"),
 job:T("Write a short policy brief that defines the issue, compares options on evidence and lists what must be checked","كتابة ورقة سياسات قصيرة بتعرّف المشكلة وتقارن البدائل بالأدلة وتحدد اللي لازم يتراجع"),
 in:T("Issue statement and scope|Service statistics and complaints data|Current procedures|Stakeholder views","وصف المشكلة ونطاقها|إحصاءات الخدمة وبيانات الشكاوى|الإجراءات الحالية|آراء أصحاب المصلحة"),
 out:T("Problem statement with data|Options table (option, benefit, cost, risk, time)|Items needing legal or financial review|Two-page brief","تعريف المشكلة بالبيانات|جدول البدائل (البديل، الفايدة، التكلفة، المخاطرة، الوقت)|بنود محتاجة مراجعة قانونية أو مالية|ورقة من صفحتين"),
 resp:T("Include the status quo as an option|Tie every claim to a data source or mark it as assumption|List who must be consulted","حط الوضع الحالي كبديل|اربط كل ادعاء بمصدر بيانات أو علّمه افتراض|حدد مين لازم يتم استشارته"),
 guard:T("Never state what the law requires; flag legal questions for the legal department|Never present a recommendation as an official decision|Do not cite statistics that are not in the provided data","ممنوع تقول القانون بيلزم بإيه؛ علّم الأسئلة القانونية للإدارة القانونية|ممنوع تعرض التوصية كقرار رسمي|ماتستشهدش بإحصاءات مش موجودة في البيانات المقدمة"),
 task:T("Issue: permit processing takes [21] days on average against a [10]-day standard. Data: [paste monthly volumes and complaints]. Write a two-page brief with 3 options including status quo, and list items needing legal review.","المشكلة: استخراج التصريح بياخد في المتوسط [21] يوم مقابل معيار [10] أيام. البيانات: [الصق الأعداد الشهرية والشكاوى]. اكتب ورقة من صفحتين فيها 3 بدائل منهم الوضع الحالي، وحدد البنود اللي محتاجة مراجعة قانونية."),
 sk:"gov-performance-policy-brief"}
 ],
 skills:[
{k:"gov-citizen-request-triage",n:T("Citizen request triage","فرز طلبات المواطنين"),
 when:T("Use when the user shares citizen requests or complaints and asks to sort, prioritise, find patterns or draft replies.","استخدمها لما المستخدم يشارك طلبات أو شكاوى مواطنين ويطلب فرزها أو ترتيب أولوياتها أو استخراج أنماط أو صياغة ردود."),
 steps:T("Confirm the date, services and service standard in days|Mask national IDs and phone numbers|Compute days open per request and compare with the standard|Assign each request one service, one owner and a priority|Group repeating issues into themes with example refs|Draft replies only from approved templates and mark gaps|Write a 5-line note for the supervisor","أكد التاريخ والخدمات ومعيار الخدمة بالأيام|اخفِ الأرقام القومية والتليفونات|احسب أيام الفتح لكل طلب وقارنها بالمعيار|حدد لكل طلب خدمة ومسؤول وأولوية|جمّع المشاكل المتكررة في محاور بأمثلة مراجع|اكتب ردود من القوالب المعتمدة بس وعلّم الفجوات|اكتب ملاحظة من 5 سطور للمشرف"),
 out:T("Triage table (ref, service, days open, standard, priority, owner) + themes table (theme, count, refs) + draft replies + supervisor note","جدول فرز (المرجع، الخدمة، أيام الفتح، المعيار، الأولوية، المسؤول) + جدول محاور (المحور، العدد، المراجع) + ردود مقترحة + ملاحظة للمشرف"),
 checks:T("Request count in the table equals the input count|Every overdue request appears in the priority list|No personal identifiers appear in the output","عدد الطلبات في الجدول بيساوي عدد المدخلات|كل طلب متأخر موجود في قائمة الأولوية|مفيش بيانات تعريف شخصية في المخرج")},
{k:"gov-tender-evaluation-pack",n:T("Tender evaluation pack","ملف تقييم العطاءات"),
 when:T("Use when the user shares tender criteria and bids and asks for a comparison or evaluation support for a committee.","استخدمها لما المستخدم يشارك معايير مناقصة وعطاءات ويطلب مقارنة أو دعم تقييم للجنة."),
 steps:T("List the published criteria and weights exactly as written|Check each bid against the mandatory documents list|Extract each bid’s values per criterion with the source page|Mark missing or unclear values and draft clarification questions|Build the comparison table without scores or ranking|Write a neutral summary of differences for the committee","اكتب المعايير والأوزان المعلنة زي ما هي|راجع كل عطاء على قائمة المستندات الإلزامية|استخرج قيم كل عطاء لكل معيار برقم الصفحة|علّم القيم الناقصة أو المش واضحة واكتب أسئلة استيضاح|اعمل جدول المقارنة من غير درجات أو ترتيب|اكتب ملخص محايد للفروق للجنة"),
 out:T("Compliance table (bidder, item, present or missing) + comparison table (criterion, weight, bidder values, source page) + clarification questions + neutral summary","جدول استيفاء (المتقدم، المستند، موجود أو ناقص) + جدول مقارنة (المعيار، الوزن، قيم المتقدمين، الصفحة) + أسئلة استيضاح + ملخص محايد"),
 checks:T("Only published criteria are used|Every value has a source page or is marked missing|No winner, score or ranking appears","مستخدم المعايير المعلنة بس|كل قيمة ليها صفحة أو متعلمة ناقصة|مفيش فائز أو درجات أو ترتيب")},
{k:"gov-performance-policy-brief",n:T("Performance report and policy brief","تقرير الأداء وورقة السياسات"),
 when:T("Use when the user asks for a KPI or initiatives report, or an options paper on a public service issue for decision makers.","استخدمها لما المستخدم يطلب تقرير مؤشرات أو مبادرات، أو ورقة بدائل في قضية خدمة عامة لصناع القرار."),
 steps:T("Confirm the period, the audience and the RAG or decision rule|Compute gaps from the data exactly as provided|Explain each red item or the core problem with sourced reasons|Lay out options including the status quo with benefit, cost, risk and time|Separate decisions needed from information|Flag legal and financial questions for the right department|Write the one or two-page summary","أكد الفترة والجمهور وقاعدة الألوان أو القرار|احسب الفجوات من البيانات زي ما هي|اشرح كل بند أحمر أو المشكلة الأساسية بأسباب ليها مصدر|اعرض البدائل ومنها الوضع الحالي بالفايدة والتكلفة والمخاطرة والوقت|افصل القرارات المطلوبة عن المعلومات|علّم الأسئلة القانونية والمالية للإدارة المختصة|اكتب الملخص في صفحة أو صفحتين"),
 out:T("Status table (KPI, target, actual, gap, RAG) or options table (option, benefit, cost, risk, time) + decisions list + review flags + summary","جدول حالة (المؤشر، المستهدف، الفعلي، الفجوة، اللون) أو جدول بدائل (البديل، الفايدة، التكلفة، المخاطرة، الوقت) + قائمة القرارات + تنبيهات المراجعة + ملخص"),
 checks:T("Gaps recompute correctly from the input|Every reason has an owner or a source|Status quo is included when options are compared|No statement claims to be an official decision","الفجوات بتتحسب صح من المدخلات|كل سبب ليه مسؤول أو مصدر|الوضع الحالي موجود لما بنقارن بدائل|مفيش جملة بتدّعي إنها قرار رسمي")}
 ],
 conn:[
{t:T("Citizen requests inbox triage","فرز صندوق طلبات المواطنين"),conn:"email",
 reads:T("Read-only access to the citizen services shared mailbox for the last working day","قراءة فقط لصندوق بريد خدمة المواطنين المشترك لآخر يوم عمل"),
 writes:T("Reply drafts saved in the mailbox, never sent","مسودات ردود محفوظة في الصندوق، من غير إرسال"),
 approval:T("The citizen services officer reviews and sends each reply","مسؤول خدمة المواطنين يراجع ويرسل كل رد"),
 pr:PR("Connector — citizen inbox triage","Connector — فرز صندوق المواطنين",["Citizen services supervisor at a public-sector entity in Egypt or the Gulf","Read yesterday’s emails in the citizen services mailbox, triage them and save reply drafts","- Mailbox: [citizen services shared mailbox], read-only plus drafts\n- Service standards: [paste services and days]\n- Approved reply templates: [paste]","Overdue requests and anything sensitive must reach a person first","- Every email from [date] is in the triage table\n- Up to 15 drafts saved, none sent","Triage table (sender masked, service, days open, priority, owner) + list of drafts saved, in Arabic."],["مشرف خدمة مواطنين في جهة حكومية في مصر أو الخليج","اقرا إيميلات امبارح في صندوق خدمة المواطنين، وافرزها، واحفظ مسودات ردود","- الصندوق: [صندوق خدمة المواطنين المشترك]، قراءة ومسودات بس\n- معايير الخدمة: [الصق الخدمات والأيام]\n- قوالب الردود المعتمدة: [الصق]","الطلبات المتأخرة وأي حاجة حساسة لازم توصل لشخص الأول","- كل إيميل من [التاريخ] موجود في جدول الفرز\n- لحد 15 مسودة محفوظة، ومفيش حاجة اتبعتت","جدول فرز (المرسل مخفي، الخدمة، أيام الفتح، الأولوية، المسؤول) + قائمة المسودات المحفوظة، بالعربي."])},
{t:T("Tender documents comparison","مقارنة مستندات المناقصة"),conn:"drive",
 reads:T("Read-only access to the tender folder: published criteria and submitted bid files","قراءة فقط لفولدر المناقصة: المعايير المعلنة وملفات العطاءات المقدمة"),
 writes:T("One draft comparison document saved in a committee working folder","مستند مقارنة واحد كمسودة في فولدر عمل اللجنة"),
 approval:T("The evaluation committee secretary reviews the draft before any committee member sees it","أمين لجنة التقييم يراجع المسودة قبل ما أي عضو يشوفها"),
 pr:PR("Connector — tender comparison from the drive","Connector — مقارنة المناقصة من الدرايف",["Procurement officer supporting a bid evaluation committee in a public entity","Read the tender folder and prepare a neutral compliance and criteria comparison draft","- Folder: [tender folder name], read-only\n- Criteria and weights: from [criteria file]\n- Mandatory documents list: [paste]","Neutrality and traceability matter more than speed","- Every bid file in the folder is covered\n- Every value cites a file and page; 0 rankings or scores","Compliance table + comparison table + clarification questions, saved as one draft document, in Arabic."],["مسؤول مشتريات بيدعم لجنة تقييم عطاءات في جهة حكومية","اقرا فولدر المناقصة وجهّز مسودة مقارنة محايدة للاستيفاء والمعايير","- الفولدر: [اسم فولدر المناقصة]، قراءة فقط\n- المعايير والأوزان: من [ملف المعايير]\n- قائمة المستندات الإلزامية: [الصق]","الحياد وإمكانية التتبع أهم من السرعة","- كل ملف عطاء في الفولدر متغطي\n- كل قيمة ليها ملف وصفحة؛ و0 ترتيب أو درجات","جدول استيفاء + جدول مقارنة + أسئلة استيضاح، محفوظين كمسودة مستند واحد، بالعربي."])},
{t:T("Monthly KPI pull from the performance sheet","سحب المؤشرات الشهرية من شيت الأداء"),conn:"sheets",
 reads:T("Read-only access to the KPI tracking spreadsheet and initiatives tab","قراءة فقط لشيت متابعة المؤشرات وتاب المبادرات"),
 writes:T("No writes to the source sheet; the report is returned as a draft","مفيش كتابة في الشيت الأصلي؛ التقرير بيرجع كمسودة"),
 approval:T("The head of strategy approves the report before circulation","رئيس الاستراتيجية يعتمد التقرير قبل توزيعه"),
 pr:PR("Connector — monthly KPI report","Connector — تقرير المؤشرات الشهري",["Performance analyst in the strategy office of a government entity in the Gulf or Egypt","Read the KPI sheet for [month] and draft the monthly performance report","- Sheet: [KPI tracker], tabs KPIs and Initiatives, read-only\n- RAG rule: [green at target, amber within 10%, red below]\n- Owner comments column: [column name]","Leadership needs decisions, not a data dump","- All KPIs for the month are in the status table\n- Up to 3 decisions listed","Status table + delayed milestones + decisions + one-page summary, in Arabic."],["محلل أداء في مكتب الاستراتيجية في جهة حكومية في الخليج أو مصر","اقرا شيت المؤشرات لشهر [الشهر] واكتب مسودة تقرير الأداء الشهري","- الشيت: [متابعة المؤشرات]، تابات المؤشرات والمبادرات، قراءة فقط\n- قاعدة الألوان: [أخضر عند المستهدف، أصفر في حدود 10%، أحمر أقل]\n- عمود تعليقات المسؤولين: [اسم العمود]","القيادة محتاجة قرارات، مش كومة أرقام","- كل مؤشرات الشهر في جدول الحالة\n- لحد 3 قرارات","جدول الحالة + المراحل المتأخرة + القرارات + ملخص صفحة، بالعربي."])}
 ]
};
